"""Build 13 exact native screenshot pairs; never modify or substitute images."""
from pathlib import Path
from collections import Counter
import json,hashlib,html,struct
HERE=Path(__file__).resolve().parent
DATA=json.loads((HERE/'gallery-data.json').read_text(encoding='utf-8'))
STYLE='\n:root{--paper:#f3efe7;--ink:#292e2a;--muted:#647065;--line:#d7d6cb;--green:#254e43;--gold:#9b6339;--panel:#fcfbf7;--radius:14px}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.6 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}a{color:var(--green);text-underline-offset:4px}button,input{font:inherit}button,a,input,summary{touch-action:manipulation}button:focus-visible,a:focus-visible,input:focus-visible,summary:focus-visible{outline:3px solid #c88734;outline-offset:4px}button{cursor:pointer}.wrap{width:min(1380px,94vw);margin:auto}.hero{padding:62px 0 28px;border-bottom:1px solid var(--line)}.eyebrow,.category{font-size:12px;font-weight:750;letter-spacing:.11em;text-transform:uppercase;color:var(--gold)}h1,h2,h3,p{margin:0}h1{font:500 clamp(36px,5.5vw,68px)/1.08 Georgia,serif;letter-spacing:-.04em;max-width:1050px;margin:15px 0 20px}h2{font:500 31px/1.2 Georgia,serif}h3{font-size:20px;line-height:1.35;margin-top:5px}.intro{max-width:960px;font-size:19px;color:#526052}.badges{display:flex;flex-wrap:wrap;gap:9px;margin-top:25px}.badge{font-size:14px;padding:6px 12px;background:#e5ece4;border-radius:40px;color:var(--green)}.baseline-notice{margin:25px 0 0;border-left:3px solid var(--gold);padding:12px 18px;max-width:1050px;background:#eee6d9}.baseline-notice strong{display:block;font-size:14px}.baseline-notice p{font-size:14px;color:#5d594e;margin-top:3px}.toolbar{position:sticky;top:0;z-index:10;background:rgba(243,239,231,.97);backdrop-filter:blur(12px);padding:16px 0;border-bottom:1px solid var(--line)}.toolbar-inner{display:flex;align-items:center;justify-content:space-between;gap:15px}.filters{display:flex;gap:7px;flex-wrap:wrap}.filters button,.mode-buttons button{border:1px solid var(--line);background:var(--panel);color:var(--ink);border-radius:30px;padding:7px 15px;font-size:14px}.filters button[aria-pressed=true],.mode-buttons button[aria-pressed=true]{background:var(--green);border-color:var(--green);color:white}.load-count{font-size:13px;color:var(--muted);white-space:nowrap}.section-lead{display:flex;align-items:baseline;justify-content:space-between;gap:20px;margin:40px 0 22px}.section-lead p{font-size:14px;color:var(--muted);max-width:650px}.cards{display:grid;gap:26px}.comparison,.single-card{background:var(--panel);border:1px solid var(--line);border-radius:var(--radius);overflow:hidden;box-shadow:0 3px 15px #25322806}.card-header{padding:21px 24px;display:flex;justify-content:space-between;gap:20px;align-items:center}.capture-status{font-size:12px;color:var(--muted);text-align:right}.capture-status.ready{color:var(--green)}.image-stage,.single-stage{position:relative;background:#171d1b;aspect-ratio:16/9;isolation:isolate}.image-stage figure{position:absolute;inset:0;margin:0;width:100%;height:100%;z-index:1;background:#171d1b}.image-stage img,.single-stage img{width:100%;height:100%;object-fit:contain;display:block;opacity:0}.image-stage img.loaded,.single-stage img.loaded{opacity:1}.image-stage figcaption{position:absolute;top:14px;padding:6px 11px;background:#162a26df;color:white;max-width:45%;font-size:13px;border:1px solid #ffffff35;border-radius:6px}.image-before figcaption{left:14px}.image-after figcaption{right:14px}.image-stage[data-mode=after] .image-before,.image-stage[data-mode=before] .image-after{display:none}.image-stage[data-mode=compare] .image-after{clip-path:inset(0 calc(100% - var(--split)) 0 0)}.image-stage[data-mode=compare] .image-after figcaption{left:14px;right:auto}.image-stage[data-mode=compare] .image-before figcaption{right:14px;left:auto}.split-line{display:none;position:absolute;inset:0 auto 0 var(--split);width:2px;background:white;z-index:3;pointer-events:none;box-shadow:0 0 5px #0009}.split-line b{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);background:var(--green);color:white;border:2px solid white;width:38px;height:38px;line-height:32px;text-align:center;border-radius:50%}.image-stage[data-mode=compare] .split-line{display:block}.image-stage[data-mode=side]{aspect-ratio:32/9;display:grid;grid-template-columns:1fr 1fr;gap:2px}.image-stage[data-mode=side] figure{position:relative;inset:auto;height:auto;aspect-ratio:16/9}.image-stage[data-mode=side] figcaption{font-size:11px;max-width:80%;top:8px}.empty-state{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;text-align:center;padding:30px;color:#a7b5ac;font-size:14px;z-index:0}.image-stage figure:has(img:not(.loaded)){background:transparent}.comparison-controls{padding:17px 24px;display:flex;align-items:center;gap:18px;flex-wrap:wrap;border-bottom:1px solid #e8e6df}.mode-buttons{display:flex;gap:6px;flex-wrap:wrap}.mode-buttons button{padding:6px 13px;font-size:13px}.slider-control{display:flex;align-items:center;gap:10px;font-size:12px;color:var(--muted)}.slider-control[hidden]{display:none}.slider-control input{width:180px;accent-color:var(--green)}.slider-control output{min-width:38px}.image-links{display:flex;gap:15px;margin-left:auto;font-size:12px}.caption{padding:20px 24px 13px;font-size:15px;max-width:1150px}.baseline{margin:0 24px 22px;font-size:13px;color:var(--muted)}.baseline summary{cursor:pointer}.baseline p{padding-top:8px;max-width:1000px}.fire-grid{display:grid;grid-template-columns:1fr 1fr;gap:22px;margin-top:26px}.original-link{display:inline-block;margin:0 24px 23px;font-size:13px}.context{display:grid;grid-template-columns:1fr 1fr;gap:28px;margin:48px 0}.context>section{padding:27px;background:#e9e9df;border:1px solid var(--line);border-radius:var(--radius)}.context h2{font-size:26px;margin-bottom:16px}.context p,.context li{font-size:14px;color:#556052}.context ul{margin:12px 0 0;padding-left:20px}.context li+li{margin-top:8px}.map{width:100%;height:auto;display:block;margin:10px 0 6px}.map text{font-family:system-ui,sans-serif}.coords{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:12px}.coords strong{font-size:14px}.coords code{display:block;font-size:12px;color:#536056;white-space:nowrap}.coords p{font-size:12px;margin-top:5px}.footer{padding:10px 0 45px;border-top:1px solid var(--line);color:var(--muted);font-size:12px}.footer p{margin-top:12px}.hidden{display:none!important}.jump{color:var(--green);font-size:14px;white-space:nowrap}@media(max-width:760px){.hero{padding-top:32px}.intro{font-size:16px}.toolbar-inner{display:block}.load-count{margin-top:10px}.filters button{padding:6px 10px;font-size:12px}.section-lead{display:block}.section-lead p{margin-top:10px}.card-header{padding:17px;display:block}.capture-status{display:block;text-align:left;margin-top:8px}h3{font-size:18px}.comparison-controls{padding:14px;gap:13px}.image-links{margin-left:0}.caption{padding:16px}.baseline{margin:0 16px 18px}.fire-grid,.context{grid-template-columns:1fr}.image-stage figcaption{font-size:10px;top:7px;padding:4px 7px;max-width:47%}.image-before figcaption{left:7px}.image-after figcaption{right:7px}.image-stage[data-mode=side]{display:block;aspect-ratio:auto}.image-stage[data-mode=side] figure{width:100%}.coords{grid-template-columns:1fr}.slider-control input{width:150px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}\n\n.image-stage.pending{aspect-ratio:auto;min-height:200px}.image-stage img{opacity:1}.empty-state{position:relative;min-height:200px;display:block;padding:45px}.empty-state p{margin-top:12px}.comparison-controls[hidden]{display:none}.map text{font-size:12px}.map .map-key{font-size:10px}button:disabled{opacity:.4;cursor:default}'

CONTRACT=('house1-overview','house1-front','house1-side','house1-roof','house2-front','house2-roof','house-east','house-west','house-low','house-north','interior-contact','fire-wca','fire-wcb')
assert tuple(r['id'] for r in DATA['comparisons'])==CONTRACT
assert Counter(r['baseline_key'] for r in DATA['comparisons'])=={'geometry':10,'contact':1,'fire':2}
assert DATA['scope']=={'houses':6,'final_openings':9,'rooms':8,'inhabited_rooms':5}
def e(value):return html.escape(str(value),quote=True)
def capture(name,state):
    relative=f'images/{name}-{state}.png';path=HERE/relative
    row={'file':relative,'pair':name,'state':state,'exists':path.is_file(),'usable':False}
    if not path.is_file():row['reason']='capture en attente';return row
    raw=path.read_bytes();digest=hashlib.sha256(raw).hexdigest();row.update(bytes=len(raw),sha256=digest)
    if len(raw)<24 or raw[:8]!=b'\x89PNG\r\n\x1a\n' or raw[12:16]!=b'IHDR':row['reason']='PNG incomplet ou invalide';return row
    row['width'],row['height']=struct.unpack('>II',raw[16:24])
    if not row['width'] or not row['height']:row['reason']='dimensions PNG invalides';return row
    if digest in DATA.get('obsolete_capture_sha256',{}).get(relative,[]):row['reason']='ancienne capture R3 : capture du lot actuel en attente';return row
    row['usable']=True;row['reason']='fichier disponible';return row
CAPTURES={(name,state):capture(name,state) for name in CONTRACT for state in ('before','after')}
def card(row):
    before=CAPTURES[row['id'],'before'];after=CAPTURES[row['id'],'after'];ready=before['usable'] and after['usable'];baseline=DATA['baselines'][row['baseline_key']]
    if ready:
        figures=[]
        for state,item in [('before',before),('after',after)]:
            url=e(item['file'])+'?v='+item['sha256'][:16]
            figures.append(f'<figure class="image-{state}"><img class="loaded" src="{url}" alt="{e(row["title"])} — {e(row[state+"_label"])}" loading="lazy"><figcaption>{e(row[state+"_label"])}</figcaption></figure>')
        images=''.join(figures)+'<span class="split-line" aria-hidden="true"><b>↔</b></span>'
        same=(before['width'],before['height'])==(after['width'],after['height'])
        buttons=''.join(f'<button data-mode="{mode}" aria-pressed="{str(mode=="after").lower()}"'+(' disabled' if mode=='compare' and not same else '')+f'>{label}</button>' for mode,label in [('before','Avant'),('compare','Comparer'),('after','Après'),('side','Côte à côte')])
        links=''.join(f'<a href="{e(item["file"])}?v={item["sha256"][:16]}" target="_blank" rel="noopener">Ouvrir {label} ↗</a>' for item,label in [(before,'l’avant'),(after,'l’après')])
        controls=f'<div class="comparison-controls"><div class="mode-buttons">{buttons}</div><label class="slider-control" hidden>Partie après <input type="range" min="0" max="100" value="50" aria-label="Partie après visible"><output>50 %</output></label><div class="image-links">{links}</div></div>'
        if not same:controls+='<p class="caption">Résolutions différentes : le curseur superposé est désactivé ; les images restent visibles séparément ou côte à côte.</p>'
    else:
        detail=' · '.join(label+' : '+item['reason'] for label,item in [('Avant',before),('Après',after)])
        images=f'<div class="empty-state"><strong>Capture en attente</strong><p>{e(detail)}</p><p>La comparaison apparaîtra lorsque les deux fichiers exacts seront disponibles.</p></div>';controls=''
    return f"""<article class="comparison" data-group="{e(row['group'])}" data-ready="{str(ready).lower()}" id="{e(row['id'])}"><header class="card-header"><div><span class="category">{e(baseline['label'])}</span><h3>{e(row['title'])}</h3></div><span class="capture-status {'ready' if ready else ''}">{'Avant et après disponibles' if ready else 'Capture en attente'}</span></header><div class="image-stage {'pending' if not ready else ''}" data-mode="after" style="--split:50%">{images}</div>{controls}<p class="caption">{e(row['caption'])}</p><details class="baseline"><summary>Versions comparées et provenance</summary><p><b>Avant :</b> {e(baseline['before'])}</p><p><b>Après :</b> {e(baseline['after'])}</p><p>Fichiers exacts : <code>{e(before['file'])}</code> et <code>{e(after['file'])}</code>. Leur présence ne constitue pas une validation du rendu. Les empreintes figurent dans l’index des captures.</p></details></article>"""
def map_svg():
    places=DATA['landmarks'];xs=[p['position'][0] for p in places];zs=[p['position'][2] for p in places];scale=min(450/(max(xs)-min(xs)),220/(max(zs)-min(zs)));marks=[]
    for p in places:
        x=50+(p['position'][0]-min(xs))*scale;y=35+(p['position'][2]-min(zs))*scale;end=x>450;lx=x-12 if end else x+12
        marks.append(f'<circle cx="{x:.2f}" cy="{y:.2f}" r="6" fill="#254e43"/><text x="{lx:.2f}" y="{y-10:.2f}" text-anchor="{"end" if end else "start"}" fill="#254e43">{e(p["name"])}</text>')
    return '<svg class="map" viewBox="0 0 560 300" role="img" aria-label="Positions relatives des six maisons, schéma X Z à échelle identique"><rect width="560" height="300" rx="10" fill="#e2e5d9"/>'+''.join(marks)+'<text x="20" y="286" class="map-key" fill="#647065">+X vers la droite · −Z vers le haut</text></svg>'
SCRIPT="""
document.querySelectorAll('.comparison[data-ready="true"]').forEach(card=>{
const stage=card.querySelector('.image-stage'),slider=card.querySelector('.slider-control');
card.querySelectorAll('button[data-mode]').forEach(button=>button.addEventListener('click',()=>{stage.dataset.mode=button.dataset.mode;slider.hidden=button.dataset.mode!=='compare';card.querySelectorAll('button[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));}));
const range=card.querySelector('input[type=range]');range.addEventListener('input',()=>{stage.style.setProperty('--split',range.value+'%');card.querySelector('output').textContent=range.value+' %';});
card.querySelectorAll('img').forEach(img=>img.addEventListener('error',()=>{stage.replaceChildren();const note=document.createElement('div');note.className='empty-state';note.textContent='Capture en attente : chargement du fichier impossible. Reconstruire la galerie puis actualiser la page.';stage.append(note);stage.classList.add('pending');card.querySelector('.comparison-controls').hidden=true;card.querySelector('.capture-status').textContent='Capture en attente';card.querySelector('.capture-status').classList.remove('ready');}));
});
document.querySelectorAll('.filters button').forEach(button=>button.addEventListener('click',()=>{const filter=button.dataset.filter;document.querySelectorAll('.filters button').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));document.querySelectorAll('article[data-group]').forEach(card=>card.classList.toggle('hidden',filter!=='all'&&card.dataset.group!==filter));}));
"""
available=sum(c['usable'] for c in CAPTURES.values());complete=sum(all(CAPTURES[name,state]['usable'] for state in ('before','after')) for name in CONTRACT)
filters=[('all','Tout voir'),('house1','Maison 1'),('house2','Maison 2'),('more','Autres maisons'),('interior','Ombres de contact'),('fire','Feux')]
page=f"""<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(DATA['title'])}</title><style>{STYLE}</style></head><body><header class="hero"><div class="wrap"><div class="eyebrow">Jak 3 · Spargus · revue du lot actuel</div><h1>Six maisons, leurs intérieurs et les feux.</h1><p class="intro">Treize comparaisons natives pour examiner les changements. Les deux fenêtres autour de l’angle de la première maison doivent montrer la même pièce. Les paires manquantes restent indiquées en attente.</p><div class="badges"><span class="badge">6 maisons</span><span class="badge">9 fenêtres</span><span class="badge">8 pièces, dont 5 habitées</span><span class="badge">Captures non retouchées</span></div><aside class="baseline-notice"><strong>Trois références « avant » distinctes</strong><p><b>Maisons :</b> geometry-002, avec les textures antérieures, et non le jeu PS2 original.</p><p><b>Ombres de contact :</b> même pièce partagée, sans puis avec cet effet.</p><p><b>Feux :</b> ancien generic-obs puis nouveau feu, sur la même géométrie actuelle.</p></aside></div></header><nav class="toolbar" aria-label="Filtrer les vues"><div class="wrap toolbar-inner"><div class="filters">{''.join(f'<button data-filter="{name}" aria-pressed="{str(name=="all").lower()}">{label}</button>' for name,label in filters)}</div><div class="load-count" role="status">{complete} / 13 paires disponibles · {available} / 26 fichiers utilisables</div></div></nav><main class="wrap"><div class="section-lead"><h2>Revue visuelle</h2><p>Les images restent entières. Les modes avant, après, curseur et côte à côte sont proposés seulement lorsque les deux fichiers de la paire sont disponibles. Le ciel, les personnages et les flammes peuvent varier entre deux prises.</p></div><div class="cards">{''.join(card(row) for row in DATA['comparisons'])}</div><div class="context"><section><span class="category">Repères dans WCA</span><h2>Retrouver les six maisons</h2>{map_svg()}<p>Schéma X/Z à échelle identique, fondé sur les centres des ouvertures. Ce n’est pas une capture du jeu ni une carte des rues.</p><div class="coords">{''.join('<div><strong>'+e(p['name'])+'</strong><code>X '+str(p['position'][0])+' · Y '+str(p['position'][1])+' · Z '+str(p['position'][2])+'</code></div>' for p in DATA['landmarks'])}</div></section><section><span class="category">Portée du lot</span><h2>Ce que ces vues permettent d’examiner</h2><ul><li>Deux maisons pilotes : volumes, toitures, fenêtres et ornements.</li><li>Quatre autres maisons : nouvelles ouvertures et encadrements, avec des pièces différentes.</li><li>Une pièce partagée derrière les deux fenêtres du même étage de la maison 1.</li><li>Ombres de contact et effets de feu dans des comparaisons séparées.</li></ul><p>Ce lot ne constitue pas une reconstruction complète de toute la ville. Les pièces ne sont pas visitables. Une image fixe ne valide ni les animations, ni le déplacement des personnages.</p></section></div></main><footer class="wrap footer"><p>La galerie documente les fichiers disponibles ; elle ne délivre aucun résultat de validation native.</p><p><a href="capture-index.json">Index des captures et empreintes SHA-256</a> · <a href="gallery-data.json">Légendes et références</a>. Le registre natif est produit séparément par le flux de captures. Ce générateur ne crée ni ne modifie aucune image et ne remplace jamais un fichier manquant par une autre capture.</p></footer><script>{SCRIPT}</script></body></html>"""
(HERE/'index.html').write_text(page,encoding='utf-8')
index={'expected_pairs':13,'expected_count':26,'available_count':available,'existing_count':sum(c['exists'] for c in CAPTURES.values()),'complete_pairs':complete,'native_validation_claim':False,'capture_files':list(CAPTURES.values()),'pair_baselines':{r['id']:r['baseline_key'] for r in DATA['comparisons']}}
(HERE/'capture-index.json').write_text(json.dumps(index,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(json.dumps({'page':str(HERE/'index.html'),'comparisons':13,'expected_images':26,'usable_images':available,'complete_pairs':complete},indent=2))
